/** The image that best shows the movement: the peak pose, else the single pose. */
export function thumbnailFor(exerciseId: string): ImageSourcePropType | undefined {
  const media = EXERCISE_MEDIA[exerciseId];
  return media?.peak ?? media?.main ?? media?.start;
}
